function confirm(interchange, api) {
    for (const group of interchange.groups) {
        for (const order of group.messages) {
            const beg = order.segments.find(s => s[0] === "BEG");
            api.send(api.build("855", group.version, [["BAK", "00", "AC", beg[3], beg[5]]]));
        }
    }
}
